function Show-AppliedChanges {Show-Header;Write-Host "ALTERACOES APLICADAS" -ForegroundColor Yellow;$raw=Get-Content $script:WinOptimizerChangesFile -Raw;if(!$raw -or $raw -eq "[]"){Write-Host "Nenhuma alteracao registrada."}else{@($raw|ConvertFrom-Json)|Sort-Object Date -Descending|Format-Table Date,Category,Name,Details -AutoSize};Pause-WinOptimizer}
function New-HtmlReport {Show-Header;try{$file=Join-Path $script:WinOptimizerDataFolder ("Relatorio-"+(Get-Date -Format "yyyyMMdd-HHmmss")+".html");$os=Get-CimInstance Win32_OperatingSystem;$pc=Get-CimInstance Win32_ComputerSystem;$cpu=Get-CimInstance Win32_Processor|Select-Object -First 1;$raw=Get-Content $script:WinOptimizerChangesFile -Raw;$changes=if($raw -and $raw -ne "[]"){@($raw|ConvertFrom-Json)|ConvertTo-Html -Fragment -Property Date,Category,Name,Details|Out-String}else{"<p>Nenhuma alteracao registrada.</p>"};$html="<html><head><meta charset='utf-8'><style>body{font-family:Segoe UI;background:#07111f;color:#eaf6ff;padding:30px}.card{background:#10233b;padding:20px;border-radius:12px;margin:15px 0}h1,h2{color:#59dcff}table{width:100%;border-collapse:collapse}td,th{padding:8px;border:1px solid #31587a}</style></head><body><h1>WinOptimizer - Relatorio</h1><div class='card'><p>Windows: $($os.Caption)</p><p>Computador: $($pc.Manufacturer) $($pc.Model)</p><p>CPU: $($cpu.Name)</p></div><div class='card'><h2>Alteracoes</h2>$changes</div></body></html>";$html|Set-Content $file -Encoding UTF8;Start-Process $file;Write-Status "Relatorio criado: $file" Green;Save-AppliedChange Relatorio "HTML" $file}catch{Write-Status "Falha ao gerar relatorio." Yellow};Pause-WinOptimizer}